insert into public.products(id,name,description,category,price,stock,image_key) values
('10000000-0000-4000-8000-000000000001','모닝 세라믹 머그','손에 편안하게 감기는 부드러운 곡선. 느긋한 아침의 커피 한 잔을 위한 320ml 세라믹 머그입니다. 식기세척기 사용이 가능합니다.','키친',18000,40,'mug'),
('10000000-0000-4000-8000-000000000002','포근한 테이블 램프','공간에 따뜻한 빛을 더하는 작은 조명. 패브릭 갓과 우드 베이스가 조화를 이룹니다. 전구 포함, 유선 스위치 방식입니다.','리빙',68000,15,'lamp'),
('10000000-0000-4000-8000-000000000003','데일리 우드 체어','나무의 결이 살아 있는 간결한 의자. 식탁에서도 서재에서도 자연스럽게 어울립니다. 오크 무늬목, 폭 45cm입니다.','가구',129000,8,'chair'),
('10000000-0000-4000-8000-000000000004','가벼운 캔버스 백','책 한 권과 작은 소지품을 담는 일상의 가방. 탄탄한 면 캔버스에 안쪽 포켓을 더했습니다. 가로 34cm, 세로 38cm입니다.','라이프',26000,30,'bag'),
('10000000-0000-4000-8000-000000000005','슬로우 월 클락','숫자 대신 여백을 담은 무소음 벽시계. 하루의 속도를 조금 낮춰 보세요. 지름 25cm, AA 건전지 1개 별도입니다.','리빙',42000,20,'clock'),
('10000000-0000-4000-8000-000000000006','샌드 오브제 화병','꽃 한 송이로 완성되는 작은 풍경. 모래빛 무광 질감이 돋보이는 세라믹 화병입니다. 높이 20cm, 수작업 유약으로 질감이 조금씩 다릅니다.','리빙',34000,25,'vase')
